import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;
  const group = new Group();
  group.position.set(0, -0.2, 0);

  const timelines = [];
  let glbScene = null;

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbScene = gltf.scene;
    group.add(glbScene);

    // Apply PBR material tweaks for machined-metal look
    glbScene.traverse((child) => {
      if (child.isMesh) {
        const mat = child.material;
        if (mat) {
          mat.metalness = Math.min(mat.metalness || 0.5, 0.55);
          mat.roughness = Math.max(mat.roughness || 0.5, 0.5);
          mat.clearcoat = Math.min(mat.clearcoat || 0, 0.25);
          mat.needsUpdate = true;
        }
      }
    });
  });

  // Add accent rim light locally for hero-grade depth
  const rimLight = new ctx.THREE.PointLight(0xff2a38, 0.8, 5);
  rimLight.position.set(1.2, 0.8, -1);
  group.add(rimLight);

  // Apply parallax-scroll primitive
  const scrollPrim = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.4
  });
  timelines.push(scrollPrim.cleanup);

  // Apply magnetic-cursor primitive
  const magneticPrim = ctx.primitives['magnetic-cursor'](group, {
    radius: 1.2,
    strength: 0.35
  });
  timelines.push(magneticPrim.cleanup);

  // Hover animation: rise-in (subtle, 0.15 scene units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: -0.2 + 0.15,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  timelines.push(() => hoverTimeline.kill());

  // Entrance: weighted-settle
  const entranceTimeline = gsap.timeline();
  group.scale.set(0.95, 0.95, 0.95);
  group.position.y -= 0.4;
  entranceTimeline.to(group.position, {
    y: -0.2,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  entranceTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: false
  }, 0.1);
  timelines.push(() => entranceTimeline.kill());

  // Event handlers
  group.userData.handlers = {
    hover: (evt) => {
      hoverTimeline.play();
      const pressTimeline = gsap.timeline();
      pressTimeline.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0);
      pressTimeline.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'power2.out'
      }, 0.12);
      timelines.push(() => pressTimeline.kill());
    },
    unhover: (evt) => {
      hoverTimeline.reverse();
    },
    click: (evt) => {
      ctx.emit('hub-collection.select', { tile: config });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach((cleanup) => {
      if (typeof cleanup === 'function') cleanup();
    });
    if (glbScene) {
      glbScene.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
    rimLight.dispose();
  };

  return group;
}
